var i=`0574-kuurdak`;var a=`world-0574`;var t=`KG`;var r=`central-asia`;var o=4;var s=52;var l={en:`Kuurdak`,ua:`Куурдак`};var g={en:`A traditional dish from Kyrgyzstan, centered on lamb, beef liver, yellow onion, potato. A measured home-kitchen version organized by cooking step. Kuurdak adapted using beef liver instead of lamb liver unavailable in the catalog.`,ua:`Традиційна страва кухні країни Киргизстан. Основні складники: ягнятина, яловича печінка, жовта цибуля, картопля. Домашній варіант із кількостями продуктів за етапами приготування. Куурдак із яловичою печінкою замість баранячої, відсутньої в каталозі.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 14 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 14 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:14,i:[[`lamb`,510,`g`],[`beef-liver`,240,`g`],[`yellow-onion`,220,`g`],[`sunflower-oil`,65,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 35 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 35 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:35,i:[[`potato`,520,`g`],[`garlic`,4,`clove`],[`ground-cumin`,5,`g`],[`water`,200,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,20,`g`]]}];var u={slug:i,id:a,country:`KG`,region:r,servings:4,minutes:52,title:l,text:g,steps:d};export{t as country,u as default,a as id,s as minutes,r as region,o as servings,i as slug,d as steps,g as text,l as title};